    'tool3-para' => 'Wondershare-ի PDFelement-ը գերազանցում է սկանավորված PDF-ների փոխակերպումը իր ներկառուցված OCR-ի շնորհիվ: Օգտագործողները կարող են խմբագրել տեքստը պատկերներից և պահպանել դասավորությունները: Այն հզոր լուծում է տալիս բարդ փաստաթղթերի համար:',
    'tool3-pro1' => 'OCR տեխնոլոգիան թույլ է տալիս խմբագրել սկանավորված փաստաթղթերը',
    'tool3-pro2' => 'Ճշգրիտ պահպանում է աղյուսակները և գծապատկերները',
    'tool3-pro3' => 'Առաջարկում է խմբաքանակի փոխակերպում միանգամից մի քանի ֆայլերի համար',
    'tool3-con1' => 'Անվճար տարբերակը ելքային ֆայլերին ավելացնում է ջրանիշներ',
    'tool3-con2' => 'Ուսուցման կորը կարող է դժվար լինել նոր օգտվողների համար',
    'tool3-con3' => 'Որոշ առանձնահատկություններ պահանջում են վճարովի տարբերակը',
    'tool4-heading' => '4. Google Docs. անվճար և սկսնակների համար հարմար',
    'tool4-para' => 'Google Docs-ը PDF-ից Word-ի անվճար փոխարկիչ է, որն աշխատում է զննարկչի միջոցով: Օգտագործողները կարող են վերբեռնել PDF և արագ արտահանել այն որպես Word փաստաթուղթ: Այն հեշտ է օգտագործել և հասանելի ցանկացած վայրում:',
    'tool4-pro1' => 'Ամբողջովին անվճար Google հաշվի հետ',
    'tool4-pro2' => 'Պարզ ինտերֆեյս, որը իդեալական է սկսնակների համար',
    'tool4-pro3' => 'Աշխատում է ինտերնետ հասանելիությամբ ցանկացած սարքի վրա',
    'tool4-con1' => 'Փոխակերպման ընթացքում ձևաչափումը կարող է մի փոքր փոխվել',
    'tool4-con2' => 'Չի կարող մշակել շատ մեծ կամ բարդ PDF ֆայլեր',
    'tool4-con3' => 'Սահմանափակ առաջադեմ խմբագրում` համեմատած հատուկ ծրագրերի հետ',
    'step-by-step-heading' => 'Քայլ առ քայլ ուղեցույց. Ինչպես փոխարկել PDF-ը Word-ի',
    'step-by-step-intro' => 'Փոխակերպման գործընթացը կարող է տարբեր լինել տարբեր գործիքներում, բայց ահա թե ինչ են աշխատում առցանց փոխարկիչների մեծ մասը:',
    'step1-title' => 'Վերբեռնեք ձեր PDF-ը.',
    'step1-text' => 'Նախ, վերբեռնեք ձեր PDF ֆայլը հուսալի փոխարկիչ գործիքի վրա',
    'step2-title' => 'Ընտրեք ելքային ձևաչափը.',
    'step2-text' => 'Հաջորդը, ընտրեք Word-ը որպես ելքային ձևաչափ՝ պատշաճ խմբագրումն ապահովելու համար',
    'step3-title' => 'Անհրաժեշտության դեպքում միացրեք OCR-ը.',
    'step3-text' => 'Եթե ​​PDF-ը պարունակում է սկանավորված պատկերներ, միացրեք OCR-ը՝ տեքստը ճշգրիտ ճանաչելու համար: Այնուամենայնիվ, հիշեք, որ ոչ բոլոր գործիքներն են առաջարկում այս հնարավորությունը անվճար տարբերակներով:',
    'step4-title' => 'Ներբեռնեք Word ֆայլը.',
    'step4-text' => 'Փոխակերպման գործընթացն ավարտելուց հետո ներբեռնեք Word ֆայլը ձեր սարքում:',
    'step-by-step-final' => 'Բացեք ֆայլը և ստուգեք, որ բոլոր ձևաչափերը, աղյուսակները և տեքստը ճիշտ են հայտնվում:',
    'free-vs-paid-heading' => 'Անվճար ընդդեմ վճարովի PDF դեպի Word փոխարկիչների. ո՞րը պետք է օգտագործեք:',
    'table-feature' => 'Առանձնահատկություն',
    'table-free' => 'Անվճար PDF-ից Word փոխարկիչ',
    'table-paid' => 'Վճարովի PDF-ից Word փոխարկիչ',
    'table-speed' => 'Արագություն',
    'table-speed-free' => 'Հաճախ ավելի դանդաղ, ավելի մեծ ֆայլերով',
    'table-speed-paid' => 'Սովորաբար ավելի արագ՝ կայուն կատարողականությամբ',
    'table-limits' => 'Սահմանափակումներ',
    'table-limits-free' => 'Ունի օրական կամ ֆայլի չափի սահմանափակումներ',
    'table-limits-paid' => 'Չափի կամ քանակի խիստ սահմանափակումներ չկան',
    'table-file-size' => 'Ֆայլի չափ',
    'table-file-size-free' => 'Լավ է աշխատում միայն փոքր ֆայլերի հետ',
    'table-file-size-paid' => 'Գործում է մեծ ֆայլեր առանց խնդիրների',
    'table-formatting' => 'Ձևաչափման ճշգրտություն',
    'table-formatting-free' => 'Կարող է փոխել դասավորությունը կամ տարածությունը',
    'table-formatting-paid' => 'Պահպանում է առավելագույն ձևաչափումը ճշգրիտ',
    'table-ocr' => 'OCR որակ',
    'table-ocr-free' => 'Տեքստի ճանաչման հիմնական որակը',
    'table-ocr-paid' => 'Ընդլայնված OCR՝ ավելի լավ արդյունքներով',
    'when-to-choose-heading' => 'Երբ ընտրել ո՞ր տարբերակը:',
    'when-to-choose-para' => 'Ընտրեք անվճար PDF-ից Word փոխարկիչ, երբ աշխատում եք փոքր ֆայլերի վրա կամ արագ և պարզ փոխակերպումների կարիք ունեք: Վճարովի գործիքները լավագույնս աշխատում են, երբ շատ ֆայլեր եք մշակում, բարձր ճշգրտության կարիք ունեք և հաճախ օգտագործում եք OCR: Վճարովի տարբերակների հետ մնալը կարող է խնայել ժամանակ, երբ որակն ամենակարևորն է:',
    'common-issues-heading' => 'Ընդհանուր խնդիրներ և ինչպես շտկել դրանք',
    'common-issues-intro' => 'Առցանց գործիքներից օգտվելիս կարող եք բախվել փոխակերպման հետ կապված խնդիրների հետ: Ահա որոշ ընդհանուր խնդիրներ և ինչպես դրանք շտկել:',
    'issue1-heading' => '1. Ձևաչափման ընդմիջումներ',
    'issue1-para1' => 'Երբ PDF-ը վերածում եք Word-ի, ֆորմատավորումը երբեմն կարող է կոտրվել: Սա պարբերությունների կամ վերնագրերի տարբեր տեսք է տալիս: Հուսալի փոխարկիչի օգտագործումը կարող է օգնել պահպանել սկզբնական դասավորությունը: Word-ում ոճերը ձեռքով կարգավորելը նաև արագորեն լուծում է փոքր հավասարեցման խնդիրները: Փաստաթղթի վերջնական ավարտից առաջ էջի ընդհատումների ստուգումն ապահովում է, որ ամեն ինչ կազմակերպված է:',
    'issue1-para2' => 'Միաժամանակ փոքր հատվածների վերափոխումը հաճախ նվազեցնում է ձևաչափման սխալները:',
    'issue2-heading' => '2. Պատկերների տեղափոխում',
    'issue2-para1' => 'Պատկերները կարող են տեղաշարժվել կամ շարժվել, երբ PDF-ը վերածում եք Word-ի, հատկապես բարդ դասավորություններում: Դիզայնը պահպանող գործիքի օգտագործումն օգնում է պատկերները տեղում պահել: Փոխակերպումից հետո Word-ում պատկերների դիրքերը կարգավորելը վերականգնում է ճիշտ դասավորվածությունը: Վերջնական փաստաթուղթը որպես Word ձևանմուշ պահելը կարող է կանխել հետագա տեղաշարժերը:',
    'issue2-para2' => 'Միշտ ստուգեք աղյուսակներն ու գծապատկերները պատկերների կողքին՝ տեսողական ճշգրտությունը պահպանելու համար:',
    'issue3-heading' => '3. Տեքստի հայտնաբերման սխալները սկանավորված PDF-ներում',
    'issue3-para1' => 'Սկանավորված PDF ֆայլերը փոխակերպման ժամանակ կարող են առաջացնել տեքստի հայտնաբերման սխալներ: Փոխարկիչում OCR-ի ակտիվացումը բարելավում է տառերի և թվերի ճանաչումը: Փոխարկված Word ֆայլի վերանայումը և սխալների ուղղումը ապահովում է ճշգրտությունը: Բարձրորակ սկանավորումներն ավելի լավ արդյունքներ են տալիս և նվազեցնում ձեռքով խմբագրումը:',
    'issue3-para2' => 'OCR-ի բազմիցս օգտագործումը կարող է նաև բարելավել դժվար փաստաթղթերում ճանաչումը:',
    'conclusion-heading' => 'Եզրակացություն. 2026 թվականին PDF ֆայլերը խմբագրելու ավելի պարզ միջոց',
    'conclusion-para1' => 'PDF ֆայլերը հաճախ սահմանափակում են խմբագրումը, ուստի օգտատերերին անհրաժեշտ են գործիքներ PDF-ը Word-ի արդյունավետ փոխակերպելու համար: Ժամանակակից փոխարկիչներն այժմ պահպանում են դասավորությունները, աղյուսակները և պատկերները՝ միաժամանակ տեքստը խմբագրելի դարձնելով:',
    'conclusion-para2' => 'OCR-ի աջակցությունն օգնում է սկանավորված փաստաթղթերին՝ ապահովելով տեքստի ճշգրիտ ճանաչում: Անվճար գործիքները լավ են աշխատում փոքր ֆայլերի և արագ փոխակերպումների համար, մինչդեռ վճարովի տարբերակները մշակում են մեծ փաստաթղթերը ավելի մեծ արագությամբ և ավելի լավ ձևաչափմամբ:',
    'faqs-heading' => 'ՀՏՀ-ներ',
    'faq1-question' => 'Ո՞րն է PDF-ի Word-ի լավագույն փոխարկիչը 2026 թվականին:',
    'faq1-answer' => 'Դժվար է նշել մեկ անուն, քանի որ կան շատ հուսալի PDF-ից Word փոխակերպման գործիքներ: Այնուամենայնիվ, Adobe Acrobat Online-ն առաջարկում է բարձր ճշգրտություն և լավ պահպանում է ֆորմատավորումը: Smallpdf-ը և PDFelement-ը նույնպես հուսալի տարբերակներ են տարբեր կարիքների համար:',
    'faq2-question' => 'Կա՞ արդյոք անվճար գործիք PDF-ը Word-ի փոխարկելու համար՝ առանց ֆորմատավորումը կորցնելու:',
    'faq2-answer' => 'Google Docs-ը և Smallpdf-ն ապահովում են անվճար փոխակերպումներ՝ պատշաճ ձևաչափման պահպանմամբ: Որոշ փոքր ճշգրտումներ դեռ կարող են անհրաժեշտ լինել Word-ում:',
    'faq3-question' => 'Կարո՞ղ եմ փոխարկել սկանավորված PDF ֆայլերը:',
    'faq3-answer' => 'Այո, OCR աջակցությամբ փոխարկիչները, ինչպես օրինակ PDFelement-ը, կարող են ճանաչել տեքստը սկանավորված PDF-ներում: Ճշգրտությունը կախված է սկանավորման որակից և հստակությունից:',
    'faq4-question' => 'Ինչու՞ է ֆորմատավորումը խախտում PDF ֆայլերը փոխարկելուց հետո:',
    'faq4-answer' => 'Ֆորմատավորման ընդմիջումները տեղի են ունենում, երբ դասավորությունները, աղյուսակները կամ տառատեսակները ամբողջությամբ չեն փոխանցվում: Հուսալի փոխարկիչի օգտագործումը սովորաբար նվազագույնի է հասցնում այդ խնդիրները:',
    'faq5-question' => 'Ֆայլի չափի ի՞նչ սահմանափակումներ ունեն անվճար PDF փոխարկիչները:',
    'faq5-answer' => 'Անվճար փոխարկիչները հաճախ սահմանափակում են ամենօրյա օգտագործումը կամ ֆայլի չափը: Ավելի մեծ PDF ֆայլերը կարող են պահանջել վճարովի գործիքներ արդյունավետ մշակման համար:',
    'intro-parag' => 'Ստորև բերված է մանրամասն ուղեցույց, թե ինչպես փոխարկել PDF-ը Word-ի առավելագույն արդյունավետությամբ: Մենք նաև կքննարկենք որոշ <a href="__LINK__">վստահելի անվճար PDF-ից Word փոխարկիչներ</a>:',
    'issue2-parag' => 'Պատկերները կարող են տեղաշարժվել կամ շարժվել, երբ PDF-ը վերածում եք Word-ի, հատկապես բարդ դասավորություններում: Դիզայնը պահպանող գործիքի օգտագործումն օգնում է պատկերները տեղում պահել: Հետևելով <a href="__LINK__">մասնագետների խորհուրդներին դասավորության տեղաշարժերի վերաբերյալ</a> կարող է օգնել ձեր պատկերները պահել տեղում փոխակերպումից հետո:',
    'descriptions' => 'Փոխակերպեք PDF-ը Word-ի՝ առանց ֆորմատավորումը կորցնելու 2026 թվականին: Իմացեք լավագույն գործիքները, քայլ առ քայլ մեթոդները և փորձագիտական ​​խորհուրդները ճշգրիտ, մաքուր փոխարկումների համար: Ստուգեք հիմա:',
    'references-heading' => 'Հղումներ և մեջբերումներ',
    'ref1-title' => 'Adobe PDF-ից DOCX Reference Specification',
    'ref1-text' => 'Պաշտոնական ինժեներական փաստաթղթեր, որոնք մանրամասնում են պիտակների կառուցվածքի թարգմանությունը PDF-ից Office Open XML:',
